import Cocoa

// MARK: - AppArtwork

/// Original vector artwork generated by scripts/IconGenerator.swift and
/// shipped in the app bundle. Falls back to an SF Symbol when unavailable.
enum AppArtwork {
    static func image(named name: String, template: Bool) -> NSImage? {
        guard let image = Bundle.main.image(forResource: name) else { return nil }
        let copy = image.copy() as? NSImage ?? image
        copy.isTemplate = template
        return copy
    }
}
